CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, name text, email text UNIQUE, email_verified timestamptz, image text, role text NOT NULL DEFAULT 'member' CHECK(role IN ('member','admin')));
CREATE TABLE IF NOT EXISTS accounts (user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, type text NOT NULL, provider text NOT NULL, provider_account_id text NOT NULL, refresh_token text, access_token text, expires_at integer, token_type text, scope text, id_token text, session_state text, PRIMARY KEY(provider,provider_account_id));
CREATE TABLE IF NOT EXISTS sessions (session_token text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS verification_tokens (identifier text NOT NULL,token text NOT NULL,expires timestamptz NOT NULL,PRIMARY KEY(identifier,token));
CREATE TABLE IF NOT EXISTS member_profiles (user_id text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,demo boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS issues (id uuid PRIMARY KEY,author_id text NOT NULL REFERENCES users(id), title text NOT NULL,description text NOT NULL,category text NOT NULL CHECK(category IN ('pedestrian','accessibility','pothole')),status text NOT NULL DEFAULT 'reported' CHECK(status IN ('reported','resolution_reported','reopened')),visibility text NOT NULL DEFAULT 'public' CHECK(visibility IN ('public','hidden')),latitude double precision NOT NULL,longitude double precision NOT NULL,point geography(Point,4326) NOT NULL,location_source text NOT NULL,observation_date date NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),demo boolean NOT NULL DEFAULT false,analysis jsonb,model text);
CREATE INDEX IF NOT EXISTS issues_point_idx ON issues USING gist(point);
CREATE TABLE IF NOT EXISTS evidence (id uuid PRIMARY KEY,issue_id uuid NOT NULL REFERENCES issues(id),author_id text NOT NULL REFERENCES users(id),description text NOT NULL,observation_date date NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),visibility text NOT NULL DEFAULT 'public' CHECK(visibility IN ('public','hidden')),analysis jsonb,model text);
CREATE TABLE IF NOT EXISTS assets (id uuid PRIMARY KEY,issue_id uuid NOT NULL REFERENCES issues(id),evidence_id uuid REFERENCES evidence(id),object_key text NOT NULL UNIQUE,digest text NOT NULL,mime text NOT NULL,bytes integer NOT NULL);
CREATE TABLE IF NOT EXISTS reactions (issue_id uuid NOT NULL REFERENCES issues(id),user_id text NOT NULL REFERENCES users(id),support boolean NOT NULL DEFAULT false,confirmation_date date,revision integer NOT NULL DEFAULT 1,PRIMARY KEY(issue_id,user_id));
CREATE TABLE IF NOT EXISTS events (id uuid PRIMARY KEY,issue_id uuid NOT NULL REFERENCES issues(id),actor_id text NOT NULL REFERENCES users(id),kind text NOT NULL,reason text,evidence_id uuid REFERENCES evidence(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS flags (id uuid PRIMARY KEY,issue_id uuid NOT NULL REFERENCES issues(id),evidence_id uuid REFERENCES evidence(id),author_id text NOT NULL REFERENCES users(id),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS submissions (user_id text NOT NULL REFERENCES users(id),key text NOT NULL,digest text NOT NULL,target_id text NOT NULL,result_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,key));
CREATE TABLE IF NOT EXISTS vector_jobs (issue_id uuid PRIMARY KEY REFERENCES issues(id),attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),last_error text);
CREATE TABLE IF NOT EXISTS issue_vectors (issue_id uuid PRIMARY KEY REFERENCES issues(id),embedding vector(768) NOT NULL,config text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
